#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

/* Provided by the candidate in solution.c */
void rms_power(const int16_t *v, const int16_t *i, size_t n,
               uint32_t *vrms_out, uint32_t *irms_out, int32_t *p_out);

int main(void)
{
    static int16_t v[4096], i[4096];
    int n;
    while (scanf("%d", &n) == 1) {
        if (n < 1 || n > 4096) {
            return 1;
        }
        for (int k = 0; k < n; k++) {
            int a, b;
            if (scanf("%d %d", &a, &b) != 2) {
                return 1;
            }
            v[k] = (int16_t)a;
            i[k] = (int16_t)b;
        }
        uint32_t vr = 0, ir = 0;
        int32_t p = 0;
        rms_power(v, i, (size_t)n, &vr, &ir, &p);
        printf("%" PRIu32 " %" PRIu32 " %" PRId32 "\n", vr, ir, p);
    }
    return 0;
}
